CREATE INDEX IF NOT EXISTS idx_vsb_shop_item_active
    ON variant_sku_binding (shop_name, third_platform_item_id, active, del_flag);
CREATE INDEX IF NOT EXISTS idx_vsb_shop_variant
    ON variant_sku_binding (shop_name, third_platform_sku_id, active, del_flag);

CREATE TABLE IF NOT EXISTS variant_alignment_review (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shop_name                   VARCHAR(128)  NOT NULL,
