-- ---------------------------------------------------------------------------
-- TikTok shop ranking board (TikTok US small-shop commodity rankings).
-- A "snapshot" = one import batch, keyed by the displayed date-range string.
-- One snapshot may span multiple L1/L2/L3 categories; products carry the full
-- category path plus L1/L2/L3 splits for filtering. Future batches are
-- distinguished by the date_range field (the displayed date window) — same
-- date_range re-imported replaces the prior products (refresh semantics).
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS rank_snapshot (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shop_name      VARCHAR(128)  NOT NULL,
    date_range     VARCHAR(64)   NOT NULL,
    start_date     DATE,
    end_date       DATE,
    product_count  INT           NOT NULL DEFAULT 0,
    created_at     TIMESTAMP,
    updated_at     TIMESTAMP,
    del_flag       INT           NOT NULL DEFAULT 0
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_rank_snapshot_shop_range
    ON rank_snapshot (shop_name, date_range, del_flag);

CREATE TABLE IF NOT EXISTS rank_product (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    snapshot_id        BIGINT        NOT NULL,
    shop_name          VARCHAR(128)  NOT NULL,
    rank_no            INT,
    product_title      VARCHAR(1024),
    image_url          VARCHAR(2048),
    category_l1        VARCHAR(128),
    category_l2        VARCHAR(128),
    category_l3        VARCHAR(128),
    category_path      VARCHAR(512),
    price_usd          DECIMAL(18, 4),
    avg_price_usd      DECIMAL(18, 4),
    listed_at          DATE,
    rating             DOUBLE PRECISION,
    sales_volume       BIGINT,
    commission_rate    DOUBLE PRECISION,
    gmv_usd            DECIMAL(18, 4),
    gmv_growth_rate    DOUBLE PRECISION,
    live_gmv_usd       DECIMAL(18, 4),
    video_gmv_usd      DECIMAL(18, 4),
    card_gmv_usd       DECIMAL(18, 4),
    creator_count      INT,
    creator_order_rate DOUBLE PRECISION,
    tiktok_url         VARCHAR(2048),
    del_flag           INT           NOT NULL DEFAULT 0,
    created_at         TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_rank_product_snap
    ON rank_product (snapshot_id, shop_name, del_flag);
CREATE INDEX IF NOT EXISTS idx_rank_product_cat
    ON rank_product (snapshot_id, category_l1, del_flag);

-- ===== User Account System (P1: auth skeleton) =====

-- App users (login identity, decoupled from Shopify store auth)
CREATE TABLE IF NOT EXISTS app_user (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email               VARCHAR(255)  NOT NULL,
    password_hash       VARCHAR(255)  NOT NULL,
    name                VARCHAR(128)  NOT NULL,
    avatar_url          VARCHAR(512),
    locale              VARCHAR(8)    DEFAULT 'zh',
    timezone            VARCHAR(64)   DEFAULT 'Asia/Shanghai',
    currency            VARCHAR(8)    DEFAULT 'CNY',
    ai_response_language VARCHAR(8)   DEFAULT 'zh',
    status              VARCHAR(32)   DEFAULT 'active',
    last_login_at       TIMESTAMP,
    created_at          TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    del_flag            INT           NOT NULL DEFAULT 0
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_app_user_email ON app_user (email);

-- Refresh tokens (supports multi-device + revocation)
CREATE TABLE IF NOT EXISTS user_refresh_token (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    token_hash          VARCHAR(255)  NOT NULL,
    expires_at          TIMESTAMP     NOT NULL,
    created_at          TIMESTAMP     DEFAULT CURRENT_TIMESTAMP,
    user_agent          VARCHAR(512),
    ip                  VARCHAR(64),
    del_flag            INT           NOT NULL DEFAULT 0
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_user_refresh_token_hash ON user_refresh_token (token_hash);
CREATE INDEX IF NOT EXISTS idx_user_refresh_token_user ON user_refresh_token (user_id, del_flag);

-- ===== User Account System (P2: shop binding) =====

-- User ↔ Shop mapping. Pure junction table: unbind = physical DELETE.
-- Audit trail lives in shopify_store_auth (which retains OAuth credentials with del_flag).
-- `role` reserved for future collaborator feature; default "owner".
CREATE TABLE IF NOT EXISTS user_shop (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    shop_name           VARCHAR(128)  NOT NULL,
    shop_domain         VARCHAR(255)  NOT NULL,
    role                VARCHAR(32)   NOT NULL DEFAULT 'owner',
    bound_at            TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- One active binding per (user, shop). Re-bind after unbind reuses the row via UPSERT.
CREATE UNIQUE INDEX IF NOT EXISTS uk_user_shop ON user_shop (user_id, shop_name);
CREATE INDEX IF NOT EXISTS idx_user_shop_user ON user_shop (user_id);
CREATE INDEX IF NOT EXISTS idx_user_shop_shop ON user_shop (shop_name);

-- Short-lived OAuth state tokens (CSRF protection + user binding).
-- Created on buildInstallUrl, consumed (marked) on callback. Hard-deleted after expiry.
CREATE TABLE IF NOT EXISTS user_oauth_state (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    state_hash          VARCHAR(255)  NOT NULL,
    user_id             BIGINT        NOT NULL,
    shop_domain         VARCHAR(255)  NOT NULL,
    expires_at          TIMESTAMP     NOT NULL,
    consumed_at         TIMESTAMP,
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_user_oauth_state_hash ON user_oauth_state (state_hash);
CREATE INDEX IF NOT EXISTS idx_user_oauth_state_user ON user_oauth_state (user_id);

-- ===== P3: 账户余额系统 =====

-- 用户余额账户（一对一）。金额以分为单位存储（BIGINT），避免浮点误差。
-- lifecycle: 首次访问 /billing/overview 时由 BillingService.ensureAccount() 懒创建。
CREATE TABLE IF NOT EXISTS user_accounts (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL UNIQUE,
    balance_cny         BIGINT        NOT NULL DEFAULT 0,  -- 当前余额（分）
    total_recharged     BIGINT        NOT NULL DEFAULT 0,  -- 累计充值（分）
    total_consumed      BIGINT        NOT NULL DEFAULT 0,  -- 累计消费（分）
    total_refunded      BIGINT        NOT NULL DEFAULT 0,  -- 累计退款（分）
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 余额变动流水。每次充值/消费/退款/调整都插入一条记录，balance_before/after 便于对账。
-- type: recharge(充值) / consume(消费) / refund(退款) / adjust(人工调整)
-- ref_type: order(订单支付) / recharge(充值订单) / manual(人工调整) / subscription(订阅) / credit_pack(积分包)
-- amount_cny: 正数=入账，负数=出账
CREATE TABLE IF NOT EXISTS account_transactions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    type                VARCHAR(32)   NOT NULL,
    amount_cny          BIGINT        NOT NULL,
    balance_before      BIGINT        NOT NULL,
    balance_after       BIGINT        NOT NULL,
    ref_type            VARCHAR(32),
    ref_id              VARCHAR(64),
    remark              VARCHAR(255),
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_acc_txn_user_created ON account_transactions (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_acc_txn_ref ON account_transactions (ref_type, ref_id);

-- ===== P3.2: PayPal 支付订单 =====

-- 统一记录所有 PayPal 支付订单。purpose 区分「订单支付」与「余额充值」。
-- PayPal orderID 是天然幂等键（uk_payment_orders_paypal_order_id 唯一约束）。
-- 生命周期：created（后端创建 PayPal Order）→ approved（用户在 PayPal 弹窗批准）
--           → captured（后端 capture 成功）→ failed（capture 失败或超时）
CREATE TABLE IF NOT EXISTS payment_orders (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    paypal_order_id     VARCHAR(64)   NOT NULL,
    purpose             VARCHAR(32)   NOT NULL,   -- order_payment / balance_recharge
    ref_id              VARCHAR(64),              -- order_payment 时为 shopify_order_id；balance_recharge 时为 NULL
    amount_usd_cents    BIGINT        NOT NULL,   -- PayPal 计价用 USD（分）
    amount_cny_cents    BIGINT,                   -- balance_recharge 时记录入账 CNY（分）；order_payment 时为 NULL
    status              VARCHAR(32)   NOT NULL DEFAULT 'created',  -- created / approved / captured / failed
    paypal_capture_id   VARCHAR(64),              -- capture 成功后 PayPal 返回的 capture ID
    failure_reason      VARCHAR(255),             -- 失败原因（capture 失败时填）
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    captured_at         TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_payment_orders_paypal_order_id ON payment_orders (paypal_order_id);
CREATE INDEX IF NOT EXISTS idx_payment_orders_user ON payment_orders (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_payment_orders_ref ON payment_orders (purpose, ref_id);
CREATE INDEX IF NOT EXISTS idx_payment_orders_status ON payment_orders (status, updated_at);
-- P3.3 webhook 会按 capture_id 查 payment_orders 做幂等校验
CREATE INDEX IF NOT EXISTS idx_payment_orders_capture_id ON payment_orders (paypal_capture_id);

-- ===== P4: 积分体系 =====

-- 用户积分账户（一对一）。积分为整数，无小数。
-- 与 user_accounts 同样懒创建：首次访问 /billing/credits/balance 时由 CreditService.ensureAccount() 创建。
CREATE TABLE IF NOT EXISTS user_credits (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL UNIQUE,
    balance_credits     INT           NOT NULL DEFAULT 0,  -- 当前可用积分
    total_granted       INT           NOT NULL DEFAULT 0,  -- 累计发放
    total_consumed      INT           NOT NULL DEFAULT 0,  -- 累计消耗
    total_expired       INT           NOT NULL DEFAULT 0,  -- 累计过期
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 积分变动流水。每次发放/消耗/过期/调整都插入一条记录。
-- type: grant(发放) / consume(消耗) / expire(过期) / adjust(人工调整)
-- ref_type: subscription(订阅) / credit_pack(积分包) / marketing_api(运营中心 API) / manual
-- amount: 正数=入账，负数=出账
CREATE TABLE IF NOT EXISTS credit_transactions (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    type                VARCHAR(32)   NOT NULL,
    amount              INT           NOT NULL,
    balance_before      INT           NOT NULL,
    balance_after       INT           NOT NULL,
    ref_type            VARCHAR(32),
    ref_id              VARCHAR(64),
    endpoint            VARCHAR(128),                  -- marketing_api 时的具体接口
    remark              VARCHAR(255),
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_credit_txn_user_created ON credit_transactions (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_txn_ref ON credit_transactions (ref_type, ref_id);

-- 积分批次（支持过期，FIFO 消耗）。
-- 每次发放（订阅/积分包/促销）写一条批次记录，记录原始额度、已消耗、已过期。
-- 消耗时按 created_at ASC 顺序扣减未过期的批次（FIFO）。
-- source_type: subscription / credit_pack / promo / manual
CREATE TABLE IF NOT EXISTS credit_lots (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id             BIGINT        NOT NULL,
    source_type         VARCHAR(32)   NOT NULL,
    source_id           BIGINT,                          -- 订阅记录 ID / 积分包订单 ID / null
    amount_granted      INT           NOT NULL,
    amount_consumed     INT           NOT NULL DEFAULT 0,
    amount_expired      INT           NOT NULL DEFAULT 0,
    expires_at          TIMESTAMP,                       -- null = 永不过期
    created_at          TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_credit_lot_user_expires ON credit_lots (user_id, expires_at);
CREATE INDEX IF NOT EXISTS idx_credit_lot_user_active ON credit_lots (user_id, amount_granted, amount_consumed);

-- ===== Password reset tokens (P6 / forgot-password) =====
-- 一次性 reset token：forgot-password 生成，reset-password 消费后标记 used_at。
-- 不复用 refresh token 表，因为语义不同（reset 是一次性、短 TTL、绑定 email 上下文）。
CREATE TABLE IF NOT EXISTS user_password_reset_tokens (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT        NOT NULL,
    token_hash      VARCHAR(255)  NOT NULL UNIQUE,   -- SHA-256 hash of raw token
    expires_at      TIMESTAMP     NOT NULL,
    used_at         TIMESTAMP,                       -- null = 未使用
    ip              VARCHAR(64),
    user_agent      VARCHAR(512),
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_pwd_reset_user ON user_password_reset_tokens (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pwd_reset_hash ON user_password_reset_tokens (token_hash);

-- ===== Logistics accept decisions (P0-2) =====
-- 用户在物流页"接受"的线路决策，按 variant 粒度持久化。
-- 替代原 Next.js 本地文件 .data/logistics/{shop}-acceptances.json，支持多实例部署。
-- 唯一键 (shop_name, third_platform_sku_id, del_flag) 对应前端 upsertAcceptances 的去重逻辑。
-- JSON 字段 recommended_line_json / alternative_lines_json 存储 LogisticsLine 对象序列化。
CREATE TABLE IF NOT EXISTS logistics_accept_decision (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shop_name                VARCHAR(255)  NOT NULL,
    third_platform_item_id   VARCHAR(255)  NOT NULL,
    third_platform_sku_id    VARCHAR(255)  NOT NULL,
    quote_status             VARCHAR(32),
    recommended_line_json    TEXT,
    alternative_lines_json   TEXT,
    accepted_at              TIMESTAMP     NOT NULL,
    del_flag                 INT           NOT NULL DEFAULT 0,
    created_at               TIMESTAMP,
    updated_at               TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_lad_shop_sku
    ON logistics_accept_decision (shop_name, third_platform_sku_id, del_flag);
CREATE INDEX IF NOT EXISTS idx_lad_shop_item
    ON logistics_accept_decision (shop_name, third_platform_item_id);


